#!/usr/bin/env python3
"""gen_route2.py - writes routes/level-explore-2.txt (Agent 3, run-2 task 2, exploration run lx2 on devoff4-bin)."""
import os

HERE = os.path.dirname(os.path.abspath(__file__))
ORANGE = '"Toypad: pad 1 mode 3 lit FF 6E 00"'
L = []
add = L.append
for c in [
    "# build/agent3/toypad/routes/level-explore-2.txt - Agent 3, run-2 task 2: exploration run lx2 (devoff4-bin). Generated by",
    "# gen_route2.py. What lx1 (build/agent3/runs/20261122-195210-lx1-devoff4) showed: START at the title does nothing, the",
    "# first A does (title -> 220/528, C8 all pads white); the sidecar places the tags 2 s later; ~6 A presses on 220/534",
    "# start the story (INSTALL0 probes, 218/222, profile read, amber fade 99 42 0E); ~35 s later heavy 3D (1000-8000",
    "# draws, ~1M vertices, 10-35 fps) for ~155 s; then 766/110956 at 60 fps with the pads cycling a 6-colour rainbow",
    "# (FF 00 00, FF 6E 00, 00 6E 00, 00 6E 18, 00 00 18, FF 00 18; ~7 s a cycle) to the end (415 s), whatever A did.",
    "# This route gets there sooner, then tries other inputs one at a time (marks v-*), then the sidecar re-places the",
    "# tags (explore.ps1 -ThenMark pre-replace: REMOVE x3 + LOAD x3), then A presses to the end. FUNCTIONAL ONLY.",
    "#   powershell -NoProfile -ExecutionPolicy Bypass -File build\\agent3\\toypad\\explore.ps1 -Tag lx2-devoff4 `",
    "#     -Route build\\agent3\\toypad\\routes\\level-explore-2.txt -ThenMark pre-replace -ThenDelay 3",
]:
    add(c)
add("wait_first_frame 240")
add("mark first-frame")
add("sleep 50")
add("mark title")
add("press START")
add("sleep 3")
add("press A                                         # title -> front end (C8 all white); tags 2 s later")
add('wait_log "Toypad: pad 3 mode 1 lit FF FF FF" 25')
add("mark pads-white")
add('wait_log "Toypad listener: LOAD -> pad=3" 20')
add("mark tags-placed")
add("sleep 3")
for i in range(1, 11):
    add("press A")
    add("sleep 5")
    add("mark m%02d" % i)
add('wait_log "lit 99 42 0E" 60                       # story load: amber fade after the profile read')
add("mark story-load")
# A every ~6 s (as in lx1) until the vortex rainbow; each wait ends early on an orange fade
for i in range(1, 41):
    add("press A")
    add("wait_log %s 5" % ORANGE)
add("wait_log %s 240" % ORANGE)
add("mark vortex")
add("sleep 15")
add("mark v-idle")
tests = [
    ("press A", "v-a"),
    ("hold A 2500", "v-hold-a"),
    ("press X", "v-x"),
    ("press Y", "v-y"),
    ("press B", "v-b"),
    ("press RB", "v-rb"),
    ("press LB", "v-lb"),
    ("trigger R 255 400", "v-rt"),
    ("trigger L 255 400", "v-lt"),
    ("press RIGHT", "v-right"),
    ("press DOWN", "v-down"),
    ("stick L 0 32767 2500", "v-stick-up"),
    ("stick L 32767 0 2500", "v-stick-right"),
    ("press BACK", "v-back"),
    ("press START", "v-start"),
    ("press A", "v-start-a"),
    ("press B", "v-start-b"),
]
for cmd, mk in tests:
    add(cmd)
    add("sleep 7")
    add("mark " + mk)
add("sleep 15")
add("mark pre-replace                                # the sidecar: REMOVE x3, then LOAD x3, 3 s after this mark")
add("sleep 35")
add("mark post-replace")
for i in range(1, 61):
    add("press A")
    add("sleep 6")
    add("mark z%02d" % i)
add("stop")
out = os.path.join(HERE, "level-explore-2.txt")
with open(out, "w", newline="\r\n") as f:
    f.write("\n".join(L) + "\n")
print("wrote %s (%d lines)" % (out, len(L)))
